"use client";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { ArrowUpRight, Check, ChevronDown, Grid2X2, List, Search, X } from "lucide-react";
import Image from "next/image";
import Link from "next/link";
import { useEffect, useMemo, useState } from "react";
import type { V4Project } from "@/data/miror-v4-content";

export interface MirorProjectDirectoryProps{projects:V4Project[];pendingSlots?:number;}
export type SortMode="featured"|"title"|"location"|"category";
const labels:Record<string,string>={water:"Water & Irrigation",residential:"Residential",infrastructure:"Infrastructure",industrial:"Industrial",commercial:"Commercial",roads:"Roads & Transport",specialized:"Specialized Works"};

function Card({project,index}:{project:V4Project;index:number}){return <Link href={`/work/${project.slug}`} className="group block overflow-hidden rounded-[24px] border border-black/10 bg-[#ebe6dc] transition duration-500 hover:-translate-y-1 hover:shadow-[0_24px_80px_rgba(17,18,20,.10)]"><div className="relative aspect-[4/3] overflow-hidden"><Image src={project.cover.src} alt={project.cover.alt} fill sizes="(max-width:760px) 100vw, (max-width:1100px) 50vw, 33vw" className="object-cover transition duration-700 group-hover:scale-[1.04]"/><div className="absolute inset-0 bg-[linear-gradient(180deg,transparent_35%,rgba(0,0,0,.42))]"/><div className="absolute left-4 top-4 flex gap-2"><span className="rounded-full border border-white/20 bg-black/15 px-3 py-1.5 text-[8px] uppercase tracking-[.14em] text-white">{String(index+1).padStart(2,"0")}</span><span className="rounded-full border border-white/20 bg-black/15 px-3 py-1.5 text-[8px] uppercase tracking-[.14em] text-white">{labels[project.category]??project.category}</span></div><span className="absolute bottom-4 right-4 inline-flex h-10 w-10 items-center justify-center rounded-full bg-white text-black opacity-0 transition group-hover:opacity-100"><ArrowUpRight size={16}/></span></div><div className="p-5"><div className="flex justify-between gap-4"><span className="text-[9px] uppercase tracking-[.14em] text-black/35">{project.location}</span><span className="font-mono text-[9px] text-black/25">{project.status}</span></div><h3 className="mt-4 text-[clamp(1.5rem,2.7vw,2.5rem)] leading-[.98] tracking-[-.045em]">{project.title}</h3><p className="mt-3 line-clamp-3 text-sm leading-6 text-black/53">{project.summary}</p><div className="mt-5 flex flex-wrap gap-2">{project.scope.slice(0,3).map((scope)=><span key={scope} className="rounded-full border border-black/10 px-2.5 py-1 text-[8px] uppercase tracking-[.1em] text-black/35">{scope}</span>)}</div></div></Link>}

function ListRow({project,index}:{project:V4Project;index:number}){return <Link href={`/work/${project.slug}`} className="group grid gap-3 border-t border-black/10 py-5 md:grid-cols-[52px_1fr_280px_auto] md:items-center"><span className="font-mono text-[9px] text-black/25">{String(index+1).padStart(2,"0")}</span><span><span className="block text-lg tracking-[-.025em]">{project.title}</span><span className="mt-1 block text-[9px] uppercase tracking-[.12em] text-black/35">{project.location} · {labels[project.category]??project.category}</span></span><span className="hidden text-sm leading-6 text-black/45 md:block">{project.summary}</span><ArrowUpRight size={16} className="text-black/25 transition group-hover:-translate-y-0.5 group-hover:translate-x-0.5 group-hover:text-[#b58a37]"/></Link>}

function ReservedCard({slot}:{slot:number}){return <article className="min-h-[360px] rounded-[24px] border border-dashed border-black/15 bg-black/[.018] p-6"><div className="flex items-center justify-between"><span className="font-mono text-[9px] text-black/25">{String(slot).padStart(2,"0")}</span><span className="rounded-full border border-black/10 px-3 py-1.5 text-[8px] uppercase tracking-[.14em] text-black/35">Reserved</span></div><div className="mt-40"><p className="text-[9px] uppercase tracking-[.14em] text-black/30">Awaiting client data</p><h3 className="mt-3 text-2xl tracking-[-.04em]">Project {String(slot).padStart(2,"0")}</h3><p className="mt-2 text-sm leading-6 text-black/44">Title, location, role, scope, approved media and publication permission are required before public release.</p></div></article>}

export default function MirorProjectDirectory({projects,pendingSlots=0}:MirorProjectDirectoryProps){const reduced=useReducedMotion();const [query,setQuery]=useState("");const [category,setCategory]=useState("all");const [location,setLocation]=useState("all");const [sort,setSort]=useState<SortMode>("featured");const [view,setView]=useState<"grid"|"list">("grid");const [reserved,setReserved]=useState(false);const [page,setPage]=useState(1);const pageSize=6;const categories=useMemo(()=>["all",...Array.from(new Set(projects.map((p)=>p.category)))],[projects]);const locations=useMemo(()=>["all",...Array.from(new Set(projects.map((p)=>p.location)))],[projects]);useEffect(()=>setPage(1),[query,category,location,sort]);const filtered=useMemo(()=>{const q=query.toLowerCase().trim();const f=projects.filter((p)=>{if(category!=="all"&&p.category!==category)return false;if(location!=="all"&&p.location!==location)return false;if(q&&!`${p.title} ${p.summary} ${p.location} ${p.mirorRole} ${p.scope.join(" ")}`.toLowerCase().includes(q))return false;return true});return [...f].sort((a,b)=>sort==="title"?a.title.localeCompare(b.title):sort==="location"?a.location.localeCompare(b.location):sort==="category"?a.category.localeCompare(b.category):Number(b.featured)-Number(a.featured));},[projects,query,category,location,sort]);const pages=Math.max(1,Math.ceil(filtered.length/pageSize));const currentPage=Math.min(page,pages);const items=filtered.slice((currentPage-1)*pageSize,currentPage*pageSize);return <div className="w-full"><div className="flex flex-col gap-4 border-y border-black/10 py-4 lg:flex-row lg:items-center lg:justify-between"><div className="flex min-w-0 items-center gap-3 rounded-full border border-black/10 bg-white/20 px-4 py-2.5 lg:w-[40%]"><Search size={15} className="text-black/35"/><input value={query} onChange={(e)=>setQuery(e.target.value)} className="min-w-0 flex-1 bg-transparent text-sm outline-none" placeholder="Search projects, scope or location" aria-label="Search projects"/><button onClick={()=>setQuery("")} className={`rounded-full p-1 ${query?"opacity-100":"pointer-events-none opacity-0"}`} aria-label="Clear search"><X size={14}/></button></div><div className="flex flex-wrap items-center gap-2"><div className="hidden gap-1 lg:flex">{categories.map((item)=><button key={item} onClick={()=>setCategory(item)} className={`rounded-full px-3 py-2 text-[9px] uppercase tracking-[.12em] ${category===item?"bg-black text-white":"text-black/40 hover:bg-black/5"}`}>{item==="all"?"All":labels[item]??item}</button>)}</div><label className="hidden text-[9px] uppercase tracking-[.12em] text-black/35 md:flex md:items-center md:gap-2">Sort<select value={sort} onChange={(e)=>setSort(e.target.value as SortMode)} className="bg-transparent text-black outline-none"><option value="featured">Featured</option><option value="title">Title</option><option value="location">Location</option><option value="category">Category</option></select></label><div className="flex items-center rounded-full border border-black/10 p-1"><button onClick={()=>setView("grid")} className={`rounded-full p-2 ${view==="grid"?"bg-black text-white":"text-black/35"}`} aria-label="Grid view"><Grid2X2 size={14}/></button><button onClick={()=>setView("list")} className={`rounded-full p-2 ${view==="list"?"bg-black text-white":"text-black/35"}`} aria-label="List view"><List size={14}/></button></div><button onClick={()=>setReserved(v=>!v)} className={`rounded-full border px-3 py-2 text-[9px] uppercase tracking-[.12em] ${reserved?"border-black bg-black text-white":"border-black/10 text-black/40"}`}>Show reserved</button></div></div>{category!=="all"||location!=="all"?<div className="mt-4 flex flex-wrap gap-2"><span className="text-[9px] uppercase tracking-[.12em] text-black/30">Active filters</span>{category!=="all"?<button onClick={()=>setCategory("all")} className="inline-flex items-center gap-1 rounded-full bg-black/5 px-3 py-1.5 text-[8px] uppercase tracking-[.12em]">{labels[category]??category}<X size={11}/></button>:null}</div>:null}<div className="mt-7 flex items-center justify-between text-[9px] uppercase tracking-[.14em] text-black/30"><span>{filtered.length} published projects</span><span>{currentPage} / {pages}</span></div><AnimatePresence mode="popLayout"><div key={view} className="mt-6">{view==="grid"?<div className="grid gap-5 md:grid-cols-2 lg:grid-cols-3">{items.map((p,i)=><motion.div key={p.slug} layout initial={reduced?false:{opacity:0,y:18}} animate={{opacity:1,y:0}} transition={{duration:reduced?0:.45,delay:reduced?0:i*.03}}><Card project={p} index={(currentPage-1)*pageSize+i}/></motion.div>)}{reserved?Array.from({length:Math.min(3,pendingSlots)}).map((_,i)=><ReservedCard key={i} slot={projects.length+i+3}/>):null}</div>:<div className="border-y border-black/10">{items.map((p,i)=><ListRow key={p.slug} project={p} index={(currentPage-1)*pageSize+i}/>)}</div>}{items.length===0?<div className="rounded-[24px] border border-dashed border-black/15 p-10 text-center"><p className="text-lg">No matching projects.</p><p className="mt-2 text-sm text-black/45">Reset the filters and try again.</p><button onClick={()=>{setQuery("");setCategory("all");setLocation("all")}} className="mt-5 inline-flex items-center gap-2 rounded-full bg-black px-4 py-2.5 text-[9px] uppercase tracking-[.13em] text-white">Reset <Check size={13}/></button></div>:null}</div></AnimatePresence><div className="mt-8 flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between"><p className="text-xs text-black/32">Published records are controlled by evidence and publication permission.</p><div className="flex gap-2"><button onClick={()=>setPage((v)=>Math.max(1,v-1))} disabled={currentPage<=1} className="rounded-full border border-black/10 px-4 py-2 text-[9px] uppercase tracking-[.12em] disabled:opacity-25">Previous</button><button onClick={()=>setPage((v)=>Math.min(pages,v+1))} disabled={currentPage>=pages} className="inline-flex items-center gap-2 rounded-full bg-black px-4 py-2 text-[9px] uppercase tracking-[.12em] text-white disabled:opacity-25">Next <ChevronDown className="-rotate-90" size={13}/></button></div></div></div>}

